import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"11、【泰】 乾下坤上","description":"横渠易说 - 11、【泰】 乾下坤上","frontmatter":{"title":"11、【泰】 乾下坤上","description":"横渠易说 - 11、【泰】 乾下坤上"},"headers":[],"relativePath":"zh/classics/hengqu/013.md","filePath":"zh/classics/hengqu/013.md"}'),l={name:"zh/classics/hengqu/013.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_11、【泰】-乾下坤上" tabindex="-1">11、【泰】 乾下坤上 <a class="header-anchor" href="#_11、【泰】-乾下坤上" aria-label="Permalink to “11、【泰】 乾下坤上”">​</a></h1><h3 id="彖曰-泰小往大来吉亨-则是天地交而万物通也-上下交而其志同也。内阳而外阴-内健而外顺-内君子而外小人-君子道长-小人道消也。" tabindex="-1">彖曰：“泰小往大来吉亨”，则是天地交而万物通也，上下交而其志同也。内阳而外阴，内健而外顺，内君子而外小人，君子道长，小人道消也。 <a class="header-anchor" href="#彖曰-泰小往大来吉亨-则是天地交而万物通也-上下交而其志同也。内阳而外阴-内健而外顺-内君子而外小人-君子道长-小人道消也。" aria-label="Permalink to “彖曰：“泰小往大来吉亨”，则是天地交而万物通也，上下交而其志同也。内阳而外阴，内健而外顺，内君子而外小人，君子道长，小人道消也。”">​</a></h3><h3 id="象曰-天地交-泰-后以财成天地之道-辅相天地之宜-以左右民。" tabindex="-1">象曰：天地交，泰，后以财成天地之道，辅相天地之宜，以左右民。 <a class="header-anchor" href="#象曰-天地交-泰-后以财成天地之道-辅相天地之宜-以左右民。" aria-label="Permalink to “象曰：天地交，泰，后以财成天地之道，辅相天地之宜，以左右民。”">​</a></h3><h3 id="初九-拔茅茹-以其汇征-吉。-象曰-拔茅征吉-志在外也。" tabindex="-1">初九，拔茅茹，以其汇征，吉。 象曰：拔茅征吉，志在外也。 <a class="header-anchor" href="#初九-拔茅茹-以其汇征-吉。-象曰-拔茅征吉-志在外也。" aria-label="Permalink to “初九，拔茅茹，以其汇征，吉。 象曰：拔茅征吉，志在外也。”">​</a></h3><h3 id="九二-包荒-用冯河-不遐遗-朋亡-得尚于中行。-象曰-包荒-得尚于中行-以光大也。" tabindex="-1">九二，包荒，用冯河，不遐遗，朋亡，得尚于中行。 象曰：“包荒，得尚于中行”，以光大也。 <a class="header-anchor" href="#九二-包荒-用冯河-不遐遗-朋亡-得尚于中行。-象曰-包荒-得尚于中行-以光大也。" aria-label="Permalink to “九二，包荒，用冯河，不遐遗，朋亡，得尚于中行。 象曰：“包荒，得尚于中行”，以光大也。”">​</a></h3><p>中行，中立之行也，若朋比则未足尚也。舜文之大，不是过也。</p><h3 id="九三-无平不陂-无往不复-艰贞无咎。勿恤其孚-于食有福。-象曰-无往不复-天地际也。" tabindex="-1">九三，无平不陂，无往不复，艰贞无咎。勿恤其孚，于食有福。 象曰：“无往不复”，天地际也。 <a class="header-anchor" href="#九三-无平不陂-无往不复-艰贞无咎。勿恤其孚-于食有福。-象曰-无往不复-天地际也。" aria-label="Permalink to “九三，无平不陂，无往不复，艰贞无咎。勿恤其孚，于食有福。 象曰：“无往不复”，天地际也。”">​</a></h3><p>因交与之际以着戒，能艰贞则享福可必。</p><h3 id="六四-翩翩-不富以其邻-不戒以孚。-象曰-翩翩-不富-皆失实也。-不戒以孚-中心愿也。" tabindex="-1">六四，翩翩，不富以其邻，不戒以孚。 象曰：“翩翩”“不富”，皆失实也。“不戒以孚”，中心愿也。 <a class="header-anchor" href="#六四-翩翩-不富以其邻-不戒以孚。-象曰-翩翩-不富-皆失实也。-不戒以孚-中心愿也。" aria-label="Permalink to “六四，翩翩，不富以其邻，不戒以孚。 象曰：“翩翩”“不富”，皆失实也。“不戒以孚”，中心愿也。”">​</a></h3><p>阴阳皆未安其分，故家不富，志不宁。</p><h3 id="六五-帝乙归妹-以祉元吉。-象曰-以祉元吉-中以行愿也。" tabindex="-1">六五，帝乙归妹，以祉元吉。 象曰：“以祉元吉”，中以行愿也。 <a class="header-anchor" href="#六五-帝乙归妹-以祉元吉。-象曰-以祉元吉-中以行愿也。" aria-label="Permalink to “六五，帝乙归妹，以祉元吉。 象曰：“以祉元吉”，中以行愿也。”">​</a></h3><p>虽阴阳义反，取交际为大义。</p><h3 id="上六-城复于隍-勿用师。自邑告命-贞吝。-象曰-城复于隍-其命乱也。" tabindex="-1">上六，城复于隍，勿用师。自邑告命，贞吝。 象曰：“城复于隍”，其命乱也。 <a class="header-anchor" href="#上六-城复于隍-勿用师。自邑告命-贞吝。-象曰-城复于隍-其命乱也。" aria-label="Permalink to “上六，城复于隍，勿用师。自邑告命，贞吝。 象曰：“城复于隍”，其命乱也。”">​</a></h3><p>泰极则否，非力所支，故不可以师，其势愈乱。贞，以命令谕众，然终吝道也。故知者先几，艰贞无咎，着戒未然也。</p>',14)])])}const b=e(l,[["render",t]]);export{p as __pageData,b as default};
